            int[] calls={0};DraftAutomaticDiscovery.processGroup((system,user)->{assertEquals(1,++calls[0]);JsonNode wire=JsonUtils.parse(user),group=wire.has("group")?wire.path("group"):wire;assertTrue(bq(group).isMissingNode(),defect);return pending(group);},f.plan,f.group,true);assertEquals(1,calls[0],defect);
