    @Test void unprovidedAliasesCannotRetroactivelyValidateThePreviousReply() throws Exception {
        for(String failure:Arrays.asList("budget","provider","malformed","empty","notes-only","missing-nodes","missing-requirements","empty-arrays","unresolved-only")){
            Fixture f=new Fixture("Follow the specified distribution channel Q.");if("budget".equals(failure)){f.root.put("questionEn",String.join("",Collections.nCopies(100000,"x")));f.stamp();f.rebuild();}String descriptor=JsonUtils.write(f.plan.descriptor());int[] calls={0};String[] first={null};
            Map<String,Object> receipt=DraftAutomaticDiscovery.processGroup((system,user)->{JsonNode wire=JsonUtils.parse(user),group=wire.has("group")?wire.path("group"):wire;if(++calls[0]==1){assertTrue(bq(group).isMissingNode());JsonNode instruction=group.path("instructions").path(0);String owner=instruction.path("sourceTaskId").asText();first[0]=JsonUtils.write(obj("baselineContextRequests",Collections.singletonList("electronicTendering"),"nodes",Collections.emptyList(),"requirements",Collections.singletonList(obj("id","not_yet_supplied","sourceTaskId",owner,"sourceQuote",instruction.path("text").asText(),"kind","reference","nodeIds",Collections.singletonList("electronicTendering"),"reason","This premature alias reference must remain rejected unless an actual supported follow-up supplies it.")),"scopeRules",Collections.emptyList(),"taskOutcomes",Collections.singletonList(obj("sourceTaskId",owner,"status","unresolved","reason","Await the requested definition.")),"notes",Collections.emptyList()));return first[0];}assertFalse(bq(group).isMissingNode());if("provider".equals(failure))throw new IllegalStateException("Synthetic provider interruption");if("malformed".equals(failure))return "{";if("notes-only".equals(failure))return "{\"notes\":[\"The requested definition was read.\"]}";if("missing-nodes".equals(failure))return "{\"requirements\":[]}";if("missing-requirements".equals(failure))return "{\"nodes\":[]}";if("empty-arrays".equals(failure))return "{\"nodes\":[],\"requirements\":[]}";if("unresolved-only".equals(failure))return JsonUtils.write(obj("taskOutcomes",Collections.singletonList(obj("sourceTaskId",group.path("instructions").path(0).path("sourceTaskId").asText(),"status","unresolved","reason","Still awaiting a supported mapping."))));return "{}";},f.plan,f.group,false);
            assertEquals("budget".equals(failure)?1:2,calls[0],failure);assertEquals(first[0],receipt.get("rawResponse"));for(Object child:list(receipt.get("taskReceipts"))){assertTrue(list(map(child).get("requirements")).isEmpty(),failure);assertTrue(JsonUtils.write(map(child).get("issues")).contains("unsupported_requirement_quote_kind_or_node_reference"),failure);}assertEquals(descriptor,JsonUtils.write(f.plan.descriptor()),failure);
        }
    }

    @Test void aReadOnlyDefinitionRetainsItsReviewedPrerequisiteClosure() throws Exception {
        ObjectNode reading=DraftReferenceSupplementCompatibilityTest.source(false);reading.put("fileKey","NTT");for(String key:Arrays.asList("sourceMembers","paragraphs","guidanceNotes","groups","conditions","markerCandidates"))reading.putArray(key);add(reading,"procedure",DraftBusinessRules.standardParagraph("NTT",172)+"\n"+DraftBusinessRules.standardParagraph("NTT",173),DraftBusinessRules.standardParagraph("NTT",166));add(reading,"reader","Review the specified alternative procedure wording.","The current alternative wording.");Map<String,Object> graph=obj("sources",Collections.singletonList(obj("id","24","fileKey","NTT","format","docx","sourceSha256",reading.path("sourceSha256").asText())),"selectedDocuments",obj("NTT","24"),"graph",obj("variables",new ArrayList<>()));DraftAutomaticDiscovery.Plan initial=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),graph);List<Map<String,Object>> retained=DraftAutomaticDiscovery.receiptNodes(initial,Collections.emptyList());state(graph).put("variables",retained);for(Map<String,Object> node:retained){node.put("status","pending");map(node.get("catalogAlignment")).put("confirmed",true);map(node.get("catalogAlignment")).put("reason","Synthetic reviewer checked the variable meaning and its prerequisites.");}
        Method basis=DraftTemplateGraphService.class.getDeclaredMethod("definitionBasis",Map.class);basis.setAccessible(true);for(Map<String,Object> projected:fields(graph))for(Map<String,Object> node:retained)if(Objects.equals(node.get("id"),projected.get("id")))node.put("definitionReview",obj("confirmed",true,"basis",basis.invoke(mock(DraftTemplateGraphService.class,CALLS_REAL_METHODS),projected)));DraftAutomaticDiscovery.Plan plan=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),graph);String reader=DraftReferenceSupplementCompatibilityTest.task(plan,"reader");Field field=DraftAutomaticDiscovery.Plan.class.getDeclaredField("knownRoots");field.setAccessible(true);DraftKnownRoots.Result known=(DraftKnownRoots.Result)field.get(plan);Map<String,Map<String,Object>> view=known.forTasks(Collections.singleton(reader),Collections.singleton("otherTenderingArrangement"));assertTrue(view.containsKey("otherTenderingArrangement"));assertTrue(view.containsKey("twoEnvelopeTendering"));for(Map<String,Object> node:view.values())assertTrue(list(map(node.get("currentDefinitionReference")).get("taskIds")).isEmpty());
        Map<String,Object> prerequisite=retained.stream().filter(node->"twoEnvelopeTendering".equals(map(node.get("catalogAlignment")).get("baselineKey"))).findFirst().orElseThrow(AssertionError::new);map(prerequisite.get("definitionReview")).put("confirmed",false);plan=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),graph);known=(DraftKnownRoots.Result)field.get(plan);assertFalse(known.forTasks(Collections.singleton(reader),Collections.singleton("otherTenderingArrangement")).containsKey("otherTenderingArrangement"),"Do not supply a conditional definition without its reviewed prerequisite");
    }

