    @Test void laterRejectedNodeCannotAuthorizeTheEarlierRequirement() throws Exception {assertLocalNameIsolation("cross-round");}
    private static void assertLocalNameIsolation(String kind) throws Exception {
        Fixture f=new Fixture("Follow the specified distribution channel Q.");int[] calls={0};Map<String,Object> receipt=DraftAutomaticDiscovery.processGroup((system,user)->{JsonNode wire=JsonUtils.parse(user),group=wire.has("group")?wire.path("group"):wire;String owner=group.path("instructions").path(0).path("sourceTaskId").asText(),quote=Arrays.asList("rejected-quote","cross-round").contains(kind)?"This exact quotation is absent from the current source.":group.path("instructions").path(0).path("text").asText();Map<String,Object> node=obj("id","electronicTendering","sourceTaskId",owner,"type","boolean","role","input","nameEn","Independent local choice","sourceQuote",quote,"branches",Collections.emptyList(),"effects",Collections.emptyList());if(++calls[0]>1)return "cross-round".equals(kind)?JsonUtils.write(obj("nodes",Collections.singletonList(node))):"{}";assertTrue(bq(group).isMissingNode());ObjectNode reply=(ObjectNode)JsonUtils.parse(pending(group));reply.putArray("nodes").add(JsonUtils.mapper().valueToTree(node));if("duplicate".equals(kind))reply.withArray("nodes").add(JsonUtils.mapper().valueToTree(node));((ObjectNode)reply.path("requirements").path(0)).put("kind","input").putArray("nodeIds").add("electronicTendering");return requestDefinition(JsonUtils.write(reply));},f.plan,f.group,false);
        assertEquals(2,calls[0],kind);for(Object child:list(receipt.get("taskReceipts"))){for(Object node:list(map(child).get("nodes")))assertNotEquals(f.root.get("id"),map(node).get("id"));for(Object requirement:list(map(child).get("requirements")))assertFalse(list(map(requirement).get("nodeIds")).contains(f.root.get("id")),kind+JsonUtils.write(receipt));}String children=JsonUtils.write(receipt.get("taskReceipts"));if("valid".equals(kind))assertTrue(children.contains("Independent local choice"),JsonUtils.write(receipt));else assertTrue(children.contains("unsupported_requirement_quote_kind_or_node_reference"),kind+children);
    }

