            assertEquals(2,calls[0],part);String children=JsonUtils.write(receipt.get("taskReceipts"));if(!fresh){assertTrue(children.contains("DISCOVERY_FOREIGN_REFERENCE"),part+children);for(Object child:list(receipt.get("taskReceipts")))for(Object node:list(map(child).get("nodes"))){assertNotEquals(f.root.get("id"),map(node).get("parentId"));assertFalse(list(map(node).get("relatedInputIds")).contains(f.root.get("id")),part);}}else assertFalse(children.contains("DISCOVERY_FOREIGN_REFERENCE"),part+children);
