    private static String namespaceReply(JsonNode group,boolean repaired){
        JsonNode instruction=group.path("instructions").path(0);String owner=instruction.path("sourceTaskId").asText(),scope=instruction.path("scopeObligationIds").path(0).asText(),quote=instruction.path("text").asText();List<Object> nodes=new ArrayList<>(),requirements=new ArrayList<>();nodes.add(obj("id","site_work","sourceTaskId",owner,"type","boolean","role","input","nameEn","Site formation works included","sourceQuote",quote,"branches",Collections.emptyList(),"effects",Collections.emptyList()));requirements.add(obj("id","site_fact","sourceTaskId",owner,"sourceQuote",quote,"kind","input","nodeIds",Collections.singletonList("site_work"),"reason","Current site formation work is a separate project fact."));Map<String,Object> rule=obj("id","local_scope","sourceTaskId",owner,"scopeId",scope,"action",repaired?"check":"keep");if(!repaired)rule.put("when",obj("mode","all","clauses",Collections.singletonList(obj("inputId","site_work","operator","eq","value",true))));else{nodes.add(obj("id","local_treatment","sourceTaskId",owner,"type","boolean","role","derived","nameEn","Current conditional scope treatment","sourceQuote",quote,"branches",Collections.singletonList(obj("id","included","mode","all","clauses",Collections.singletonList(obj("inputId","site_work","operator","eq","value",true)),"resultValue",true)),"effects",Collections.singletonList(obj("scopeId",scope,"action","keep","branchId","included"))));requirements.add(obj("id","scope_treatment","sourceTaskId",owner,"sourceQuote",quote,"kind","amendment","nodeIds",Collections.singletonList("local_treatment"),"reason","Preserve the local condition through the atomic path; the named check remains review-only."));}return JsonUtils.write(obj("nodes",nodes,"requirements",requirements,"scopeRules",Collections.singletonList(rule),"taskOutcomes",Collections.singletonList(obj("sourceTaskId",owner,"status","identified","reason","Current local fact and conditional treatment require human review.")),"notes",Collections.emptyList()));
    }

